begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)select('a2530000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','dsr-nonmember253-'||i||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,3)i;
insert into public.platform_user_roles(user_id,role_code)values('a2530000-0000-4000-8000-000000000001','COMPLIANCE_MANAGER');
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b2530000-0000-4000-8000-000000000001','TEST configured controller253','TEST controller253','ACTIVE','a2530000-0000-4000-8000-000000000001'),('b2530000-0000-4000-8000-000000000002','TEST unrelated tenant253','TEST unrelated tenant253','ACTIVE','a2530000-0000-4000-8000-000000000001');
update private.platform_privacy_deployment_scope_v1 set controller_organization_id='b2530000-0000-4000-8000-000000000001',legal_approval_reference='TEST_ONLY_NONMEMBER_CONTROLLER_253',configured_at=clock_timestamp()where singleton;
insert into public.data_subject_requests(id,organization_id,request_type,subject_reference_hash,identity_verification_level,locale,status,due_at,verified_at,correlation_id,created_by)select('d2530000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i=2 then'b2530000-0000-4000-8000-000000000002'else'b2530000-0000-4000-8000-000000000001'end::uuid,'ACCESS',encode(extensions.digest(convert_to(case when i=2 then'b2530000-0000-4000-8000-000000000002'else'b2530000-0000-4000-8000-000000000001'end||':a2530000-0000-4000-8000-000000000002','UTF8'),'sha256'),'hex'),'ENHANCED','fr-MA','IN_REVIEW',now()+interval'1 day',case when i=3 then null else now()end,extensions.gen_random_uuid(),'a2530000-0000-4000-8000-000000000001'from generate_series(1,3)i;
create temporary table dsr253(k text primary key,v jsonb);grant all on dsr253 to authenticated;
select is((select count(*)from public.organization_memberships where user_id='a2530000-0000-4000-8000-000000000002'),0::bigint,'the subject has no real or invented organization membership');
set local role authenticated;select set_config('request.jwt.claim.sub','a2530000-0000-4000-8000-000000000003',true);select set_config('request.jwt.claims','{"sub":"a2530000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.confirm_my_dsr_scope_v1('d2530000-0000-4000-8000-000000000001',array['ACCOUNT'],'TEST-253-other-subject')$$,'42501','DSR_VERIFIED_SUBJECT_REQUIRED','another authenticated subject cannot bind the verified request');
select set_config('request.jwt.claim.sub','a2530000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a2530000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.confirm_my_dsr_scope_v1('d2530000-0000-4000-8000-000000000001',array['ACCOUNT'],'TEST-253-AAL1')$$,'42501','DSR_VERIFIED_SUBJECT_REQUIRED','a password-only session cannot bind account rights');
select set_config('request.jwt.claims','{"sub":"a2530000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.confirm_my_dsr_scope_v1('d2530000-0000-4000-8000-000000000002',array['ACCOUNT'],'TEST-253-arbitrary-org')$$,'42501','DSR_VERIFIED_SUBJECT_REQUIRED','even a verified hash cannot manufacture a relationship with an arbitrary tenant');
select throws_ok($$select public.confirm_my_dsr_scope_v1('d2530000-0000-4000-8000-000000000003',array['ACCOUNT'],'TEST-253-unverified')$$,'42501','DSR_VERIFIED_SUBJECT_REQUIRED','an unverified request does not acquire a subject binding');
insert into dsr253 values('scope',public.confirm_my_dsr_scope_v1('d2530000-0000-4000-8000-000000000001',array['ACCOUNT'],'TEST-253-confirmed-controller'));
select set_config('request.jwt.claim.sub','a2530000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a2530000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into dsr253 values('response',public.prepare_admin_dsr_private_response_v1('d2530000-0000-4000-8000-000000000001',(select(v->>'scope_version_id')::uuid from dsr253 where k='scope'),'TEST-253-account-response'));
reset role;
select is(private.dsr_account_subject_v1('d2530000-0000-4000-8000-000000000001'),'a2530000-0000-4000-8000-000000000002'::uuid,'staff resolves the subject from the immutable authenticated confirmation');
select is((select count(*)from public.organization_memberships where user_id='a2530000-0000-4000-8000-000000000002'),0::bigint,'preparing account rights never creates a sentinel membership');
select ok(exists(select 1 from public.dsr_private_responses_v1 where id=(select(v->>'response_id')::uuid from dsr253 where k='response')and subject_user_id='a2530000-0000-4000-8000-000000000002'and covered_scopes=array['ACCOUNT']::text[]),'the real private account response belongs to the independently verified subject');
select*from finish();rollback;
